#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

const dir = __dirname;
const keywords = ['Navy', 'SEAL', 'BUD/S', 'candidate', 'selection', 'washout'];

const artifacts = fs.readdirSync(dir)
  .filter(function(f) { return f.startsWith('_converge-') || f.startsWith('_voice-'); })
  .map(function(f) {
    try {
      var c = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8'));
      var claims = (c.coreVoice || '').split('\n')
        .filter(function(l) { return l.trim().startsWith('-'); })
        .slice(0, 3)
        .map(function(l) { return l.replace(/^-\s*/, '').slice(0, 150); });
      return {
        file: f, problem: c.problem || '', convergenceScore: c.convergenceScore || 0,
        modelCount: (c.models || []).length, claims: claims
      };
    } catch(e) { return null; }
  })
  .filter(function(a) {
    return a && (a.convergenceScore > 0.5 || keywords.some(function(k) { return (a.problem || '').includes(k); }));
  });

if (process.argv.includes('--json')) {
  console.log(JSON.stringify(artifacts, null, 2));
} else {
  console.log('# Navy SEAL Demo Deck\n');
  artifacts.forEach(function(a) {
    console.log('## ' + (a.problem || 'Unknown').slice(0, 100));
    console.log('- Convergence: ' + (a.convergenceScore * 100).toFixed(1) + '% | Models: ' + a.modelCount);
    if (a.claims.length > 0) {
      console.log('### Top Claims:');
      a.claims.forEach(function(c, i) { console.log((i + 1) + '. ' + c); });
    }
    console.log('\n---\n');
  });
}

